use crate::{Result,api::{self,Api},json,process,reference,require,server::{self,Backend},service,upstream::Upstream};
use base64::Engine;
use serde_json::json;
use std::path::Path;
use std::process::Command;
use std::time::Duration;

fn log(api:&Api,text:&str)->Result {api::wait(||Ok(api.messages()?.iter().any(|message|message.contains(text)))).map_err(|error|format!("{error}; waiting for {text:?}; logs: {:?}",api.messages()).into())}
fn sleep(milliseconds:u64) {std::thread::sleep(Duration::from_millis(milliseconds));}
pub fn run(output:&Path)->Result {
    reference::verify(output)?;let (baseline,root)=service::baseline(output)?;
    process::checked(Command::new(reference::node()).arg(crate::compat().join("cron-calendar.cjs")).current_dir(crate::root()),output,"cron-calendar",Duration::from_secs(120))?;
    for mode in ["artifact","overlap","global","produce","upload","download","mmdb","startup-plain","startup-base64","legacy"] {
        for (kind,backend) in [("node",Backend::Node(reference::node())),("rust",service::target()?)] {
            let label=format!("{kind}-schedule-{mode}");eprintln!("Schedule {label}");let upstream=Upstream::new(0)?;let mut document=baseline.clone();document["settings"]=json!({"logsMaxCount":1000});for field in ["subs","collections","files","artifacts","tokens","archives","modules"] {document[field]=json!([]);}
            let mut restored=document.clone();let mut root=root.clone();root["sub-store-logs"]=json!("[]");
            if ["upload","download"].contains(&mode) {document["settings"]["gistToken"]=json!("helper-token");document["settings"]["githubApiUrl"]=json!(format!("{}/host/gist/github",upstream.url()));if mode=="download" {restored=document.clone();restored["files"]=json!([api::file("cron-restored",None)]);upstream.state.script_gist.restore(&json!({"github":{"g1":{"description":"Auto Generated Sub-Store Backup","public":false,"files":{"Sub-Store":{"content":base64::engine::general_purpose::STANDARD.encode(json::stringify(&restored))}}}},"gitlab":{}}))?;}}
            if ["global","legacy"].contains(&mode) {document["files"]=json!([api::file("global-source",None),api::file("independent-source",None)]);document["artifacts"]=json!([{"name":"global-local","type":"file","source":"global-source","sync":true,"upload":false},{"name":"independent","type":"file","source":"independent-source","sync":true,"upload":false,"cron":"0 0 0 1 jan *"}]);}
            if mode=="produce" {document["files"]=json!([api::file("produce-source",Some("function operator(input){$substore.write('ran','#cron-produced');return input;}"))]);}
            let (state,mut environment)=service::seed(output,&label,&document,&root)?;server::set(&mut environment,"TZ","Asia/Shanghai");
            match mode {
                "upload"|"download"=>server::set(&mut environment,&format!("SUB_STORE_BACKEND_{}_CRON",mode.to_uppercase()),"* * * * * *"),
                "global"=>server::set(&mut environment,"SUB_STORE_BACKEND_SYNC_CRON","* * * * * *"),
                "legacy"=>{server::set(&mut environment,"SUB_STORE_BACKEND_CRON","* * * * * *");server::set(&mut environment,"SUB_STORE_CRON","* * * * * *");},
                "produce"=>server::set(&mut environment,"SUB_STORE_PRODUCE_CRON","* * * * * *,file,produce-source; * * * * * *,file,missing-source"),
                "mmdb"=>{for (key,value) in [("SUB_STORE_MMDB_CRON","* * * * * *".to_owned()),("SUB_STORE_MMDB_COUNTRY_URL",format!("{}/host/runtime-country",upstream.url())),("SUB_STORE_MMDB_ASN_URL",format!("{}/host/runtime-asn",upstream.url())),("SUB_STORE_MMDB_COUNTRY_PATH",state.join("country.mmdb").to_string_lossy().into_owned()),("SUB_STORE_MMDB_ASN_PATH",state.join("asn.mmdb").to_string_lossy().into_owned())] {server::set(&mut environment,key,value);}let mut files=upstream.state.runtime_files.lock().unwrap();files.insert("/host/runtime-country".into(),(200,std::fs::read(crate::compat().join("fixtures/mmdb/GeoIP2-Country-Test.mmdb"))?));files.insert("/host/runtime-asn".into(),(404,b"fixture missing".to_vec()));},
                "startup-plain"|"startup-base64"=>{restored["files"]=json!([api::file("startup-restored",None)]);let raw=json::stringify(&restored).into_bytes();let raw=if mode=="startup-base64" {base64::engine::general_purpose::STANDARD.encode(raw).into_bytes()} else {raw};upstream.state.runtime_files.lock().unwrap().insert("/host/runtime-state".into(),(200,raw));server::set(&mut environment,"SUB_STORE_DATA_URL",format!("{}/host/runtime-state",upstream.url()));server::set(&mut environment,"SUB_STORE_DATA_URL_POST","content.settings.startupPost={nil:null,zero:0,unicode:'恢复🙂'};");},_=>(),
            }
            let api=Api::start(&backend,&environment,&state,output,&label)?;
            match mode {
                "artifact"=>{
                    upstream.state.runtime_files.lock().unwrap().insert("/host/runtime-artifact".into(),(503,b"fixture scheduled failure".to_vec()));let mut source=api::file("artifact-source",Some("function operator(input){const n=Number($substore.read('#cron-attempt')||0)+1;$substore.write(String(n),'#cron-attempt');return input;}"));source["source"]=json!("remote");source["url"]=json!(format!("{}/host/runtime-artifact",upstream.url()));api.send(&json!({"method":"POST","path":"/api/files","body":source}),201)?;
                    api.send(&json!({"method":"POST","path":"/api/artifacts","body":{"name":"scheduled","displayName":"定时🙂","type":"file","source":"artifact-source","sync":true,"upload":false,"cron":"* * * * * *"}}),201)?;log(&api,"[ARTIFACT CRON] scheduled (定时🙂) * * * * * * error:")?;
                    upstream.state.runtime_files.lock().unwrap().insert("/host/runtime-artifact".into(),(200,b"fixture recovered".to_vec()));api::wait(||Ok(api.durable()?["artifacts"][0]["updated"].as_u64().is_some_and(|value|value>0)))?;log(&api,"[ARTIFACT CRON] scheduled (定时🙂) * * * * * * finished")?;
                    api.send(&json!({"method":"PATCH","path":"/api/artifact/scheduled","body":{"name":"renamed","cron":"*/2 * * * * *"}}),200)?;log(&api,"[ARTIFACT CRON] renamed (定时🙂) */2 * * * * * finished")?;
                    api.send(&json!({"method":"PATCH","path":"/api/artifact/renamed","body":{"sync":false}}),200)?;sleep(200);let before=api.stored("root.json")?["cron-attempt"].clone();sleep(2300);json::check(&api.stored("root.json")?["cron-attempt"],&before,false)?;
                    api.send(&json!({"method":"PATCH","path":"/api/artifact/renamed","body":{"sync":true,"cron":"* * * * * *"}}),200)?;api::wait(||Ok(api.stored("root.json")?["cron-attempt"].as_str().ok_or("Missing cron count")?.parse::<u64>()?>before.as_str().ok_or("Missing prior cron count")?.parse::<u64>()?))?;
                    api.send(&json!({"method":"DELETE","path":"/api/artifact/renamed?mode=permanent"}),200)?;sleep(200);let before=api.stored("root.json")?["cron-attempt"].clone();sleep(1300);json::check(&api.stored("root.json")?["cron-attempt"],&before,false)?;json::check(&api.durable()?["artifacts"],&json!([]),false)?;
                },
                "legacy"=>{for variable in ["SUB_STORE_BACKEND_CRON","SUB_STORE_CRON"] {log(&api,&format!("[SYNC CRON] {variable} 已弃用, 请使用 SUB_STORE_BACKEND_SYNC_CRON"))?;}sleep(1250);require(api.durable()?["artifacts"].as_array().ok_or("Missing artifacts")?.iter().all(|artifact|artifact.get("updated").is_none_or(|value|value.is_null()||value==0)),"Deprecated cron unexpectedly scheduled work")?;require(!api.messages()?.iter().any(|message|message.contains("[SYNC CRON] * * * * * * enabled")),"Deprecated cron enabled")?;},
                "overlap"=>{api.send(&json!({"method":"POST","path":"/api/files","body":api::file("slow-source",Some("async function operator(input){if($substore.read('#cron-active'))throw new Error('fixture overlap');$substore.write('yes','#cron-active');await new Promise(r=>setTimeout(r,2200));$substore.write('','#cron-active');return input;}"))}),201)?;api.send(&json!({"method":"POST","path":"/api/artifacts","body":{"name":"slow","type":"file","source":"slow-source","sync":true,"upload":false,"cron":"* * * * * *"}}),201)?;api::wait(||Ok(api.stored("root.json")?["cron-active"]=="yes"))?;api.send(&json!({"method":"PATCH","path":"/api/artifact/slow","body":{"displayName":"refreshed"}}),200)?;log(&api,"skipped: previous run is still running")?;api::wait(||Ok(api.messages()?.iter().any(|message|message.contains(" finished")&&message.contains("[ARTIFACT CRON]"))))?;require(!api.messages()?.iter().any(|message|message.contains("fixture overlap")),"Scheduled runs overlapped")?;api.send(&json!({"method":"PATCH","path":"/api/artifact/slow","body":{"sync":false}}),200)?;},
                "global"=>{api::wait(||Ok(api.durable()?["artifacts"][0]["updated"].as_u64().is_some_and(|value|value>0)))?;sleep(1200);require(api.durable()?["artifacts"][1].get("updated").is_none(),"Global cron ran an independently scheduled artifact")?;log(&api,"[SYNC CRON] * * * * * * finished")?;api.send(&json!({"method":"PATCH","path":"/api/artifact/global-local","body":{"upload":true}}),200)?;log(&api,"[SYNC CRON] * * * * * * error:")?;api.send(&json!({"method":"PATCH","path":"/api/artifact/global-local","body":{"upload":false}}),200)?;let before=api.durable()?["artifacts"][0]["updated"].as_u64().ok_or("Missing sync clock")?;api::wait(||Ok(api.durable()?["artifacts"][0]["updated"].as_u64().is_some_and(|value|value>before)))?;},
                "produce"=>{api::wait(||Ok(api.stored("root.json")?["cron-produced"]=="ran"))?;log(&api,"[PRODUCE CRON] file produce-source * * * * * * finished")?;log(&api,"[PRODUCE CRON] file missing-source * * * * * * error:")?;},
                "upload"=>{api::wait(||Ok(!upstream.state.script_gist.snapshot()["github"].as_object().ok_or("Missing provider")?.is_empty()))?;log(&api,"[UPLOAD CRON] * * * * * * finished")?;let snapshot=upstream.state.script_gist.snapshot();let content=snapshot["github"].as_object().ok_or("Missing gists")?.values().next().ok_or("Missing upload")?["files"]["Sub-Store"]["content"].as_str().ok_or("Missing backup")?;let value=json::parse(std::str::from_utf8(&base64::engine::general_purpose::STANDARD.decode(content)?)?)?;require(value["settings"]["gistToken"]=="helper-token" && value["settings"]["syncTime"].as_i64().is_some(),"Scheduled upload settings or clock mismatch")?;require(upstream.fixture.snapshot().iter().any(|entry|entry["method"]=="POST"&&entry["path"].as_str().is_some_and(|path|path.contains("/gists"))),"Scheduled upload did not reach provider")?;},
                "download"=>{api::wait(||Ok(api.durable()?["files"][0]["name"]=="cron-restored"))?;log(&api,"[DOWNLOAD CRON] * * * * * * finished")?;require(api.stored("root.json")?.get("sub-store").is_some(),"Scheduled download did not persist root backup")?;},
                "mmdb"=>{api::wait(||Ok(state.join("country.mmdb").exists()))?;api::wait(||Ok(api.messages()?.iter().any(|message|message.contains("download failed:")&&message.contains("runtime-asn"))))?;let expected=std::fs::read(crate::compat().join("fixtures/mmdb/GeoIP2-Country-Test.mmdb"))?;api::wait(||Ok(std::fs::read(state.join("country.mmdb"))?==expected))?;require(!state.join("asn.mmdb").exists(),"Rejected MMDB response truncated target")?;let expected=std::fs::read(crate::compat().join("fixtures/mmdb/GeoLite2-ASN-Test.mmdb"))?;upstream.state.runtime_files.lock().unwrap().insert("/host/runtime-asn".into(),(200,expected.clone()));api::wait(||Ok(state.join("asn.mmdb").exists()))?;api::wait(||Ok(std::fs::read(state.join("asn.mmdb"))?==expected))?;log(&api,"[MMDB CRON] * * * * * * finished")?;require(upstream.fixture.snapshot().iter().all(|entry|entry["method"]=="GET"),"MMDB cron changed HTTP method")?;api.send(&json!({"method":"POST","path":"/api/preview/sub?target=JSON","body":{"name":"updated-mmdb","source":"local","content":"ss://YWVzLTEyOC1nY206cGFzcw==@127.0.0.1:8388#fixture","process":[{"type":"Script Operator","args":{"content":"function operator(input){const db=new ProxyUtils.MMDB();if(db.geoip('81.2.69.160')!=='GB'||db.ipasn('1.0.0.1')!==15169)throw new Error('Refreshed databases not usable');return input;}"}}]}}),200)?;},
                _=>{api::wait(||Ok(api.durable()?["files"][0]["name"]=="startup-restored"))?;let settings=&api.durable()?["settings"]["startupPost"];json::check(settings,&json!({"nil":null,"zero":0,"unicode":"恢复🙂"}),false)?;let saved=json::parse(api.stored("root.json")?["sub-store"].as_str().ok_or("Missing startup root backup")?)?;json::check(&saved["settings"]["startupPost"],settings,false)?;},
            }
            json::write_new(output.join(format!("{label}-final.json")),&json!({"data":api.durable()?,"root":api.stored("root.json")?,"provider":upstream.state.script_gist.snapshot(),"upstream":upstream.fixture.snapshot()}))?;upstream.fixture.healthy()?;
        }
    }Ok(())
}
